    requestText,
    address: inbound.address,
    routeKey: routeKeyForAddress2(inbound.address),
    requestMessageId: inbound.messageId,
    activeAttemptId: attemptId,
    pendingFollowUpText: "",
    pendingFollowUpAttachments: [],
    pendingRequestMessageId: "",
    pendingAddress: void 0,
    pendingRouteKey: "",
