  async downloadAndTranscribe(messageId, fileKey) {
    const client = this.getLarkClient().getClient();
    if (!client?.im?.messageResource?.get) {
      throw new Error("Feishu \u97F3\u9891\u8D44\u6E90\u4E0B\u8F7D\u80FD\u529B\u4E0D\u53EF\u7528");
    }
    const tmpDir = "/tmp/feishu-audio";
    const tmpFile = `${tmpDir}/${messageId}.opus`;
    const fs19 = await import("node:fs/promises");
    const nodeFs = await import("node:fs");
    await fs19.mkdir(tmpDir, { recursive: true });
    const response = await client.im.messageResource.get({
      params: { type: "file" },
      // 音频文件用 file 类型
      path: {
        message_id: messageId,
        file_key: fileKey
      }
    });
    const stream = response.getReadableStream();
    const chunks = [];
    for await (const chunk of stream) {
      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    }
    const buffer = Buffer.concat(chunks);
    await fs19.writeFile(tmpFile, buffer);
    const { execSync: execSync2 } = await import("node:child_process");
    const transcribeScript = "/opt/.codex/skills/voice-engine/transcribe.sh";
    try {
      const text = execSync2(`bash "${transcribeScript}" "${tmpFile}"`, {
        encoding: "utf-8",
        timeout: 6e4,
        env: { ...process.env, LD_LIBRARY_PATH: "/sherpa-onnx/lib:" + (process.env.LD_LIBRARY_PATH || "") }
      }).trim();
      await fs19.unlink(tmpFile).catch(() => {
      });
      return { text };
    } catch (error) {
      await fs19.unlink(tmpFile).catch(() => {
      });
      throw error;
    }
  }
