import { spawn as spawn5 } from "node:child_process";
import fs15 from "node:fs";
import path14 from "node:path";
var CWD = "/opt";
var AGENTMEMORY_URL = "http://127.0.0.1:3111";
var TOKEN_FILE = "/opt/.agents-to-im/user-token.json";
var BASH_BLACKLIST = [
  /\brm\s+-rf\s+\/(?:\s|$)/,
  /\bsudo\b/,
  /\bmkfs\b/,
  /\bdd\s+if=/,
  /:\(\)\s*\{/,
  // fork bomb
  /\bcurl\b[^|]*\|\s*(?:sh|bash)/,
  /\bwget\b[^|]*\|\s*(?:sh|bash)/,
  /\b(?:shutdown|reboot|halt|poweroff)\b/
];
function resolveInCwd(p) {
  const abs = path14.isAbsolute(p) ? path14.normalize(p) : path14.normalize(path14.join(CWD, p));
  if (abs !== CWD && !abs.startsWith(CWD + path14.sep)) {
    return { ok: false, abs, reason: `\u8DEF\u5F84 ${abs} \u4E0D\u5728\u5141\u8BB8\u7684\u5DE5\u4F5C\u76EE\u5F55 ${CWD} \u5185` };
  }
  return { ok: true, abs };
}
async function execReadFile(args) {
  const p = String(args.path || "");
  if (!p) return "Error: \u7F3A\u5C11 path \u53C2\u6570";
  try {
    const abs = path14.isAbsolute(p) ? p : path14.join(CWD, p);
    const stat = fs15.statSync(abs);
    if (stat.isDirectory()) return `Error: ${abs} \u662F\u76EE\u5F55\uFF0C\u8BF7\u7528 list_files`;
    if (stat.size > 256 * 1024) return `Error: \u6587\u4EF6\u8FC7\u5927\uFF08${stat.size} bytes\uFF09\uFF0C\u8D85\u8FC7 256KB \u9650\u5236`;
    return fs15.readFileSync(abs, "utf-8");
  } catch (e) {
    return `Error: \u8BFB\u53D6\u5931\u8D25 - ${e.message}`;
  }
}
async function execWriteFile(args) {
  const p = String(args.path || "");
  const content = String(args.content ?? "");
  if (!p) return "Error: \u7F3A\u5C11 path \u53C2\u6570";
  const chk = resolveInCwd(p);
  if (!chk.ok) return `Error: ${chk.reason}`;
  try {
    fs15.mkdirSync(path14.dirname(chk.abs), { recursive: true });
    fs15.writeFileSync(chk.abs, content, "utf-8");
    return `OK: \u5DF2\u5199\u5165 ${chk.abs} (${content.length} \u5B57\u7B26)`;
  } catch (e) {
    return `Error: \u5199\u5165\u5931\u8D25 - ${e.message}`;
  }
}
async function execListFiles(args) {
  const p = String(args.path || "");
  if (!p) return "Error: \u7F3A\u5C11 path \u53C2\u6570";
  try {
    const abs = path14.isAbsolute(p) ? p : path14.join(CWD, p);
    const entries = fs15.readdirSync(abs, { withFileTypes: true });
    const lines = entries.map((e) => `${e.isDirectory() ? "d" : "-"} ${e.name}`);
    return lines.length ? lines.join("\n") : "(\u7A7A\u76EE\u5F55)";
  } catch (e) {
    return `Error: \u5217\u76EE\u5F55\u5931\u8D25 - ${e.message}`;
  }
}
async function execRunBash(args) {
  const command = String(args.command || "");
  if (!command) return "Error: \u7F3A\u5C11 command \u53C2\u6570";
  for (const re2 of BASH_BLACKLIST) {
    if (re2.test(command)) return `Error: \u547D\u4EE4\u88AB\u5B89\u5168\u9ED1\u540D\u5355\u62E6\u622A\uFF08\u5339\u914D ${re2}\uFF09`;
  }
  return new Promise((resolve2) => {
    const child = spawn5("bash", ["-c", command], { cwd: CWD, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let settled = false;
    const finish = (s) => {
      if (!settled) {
        settled = true;
        resolve2(s);
      }
    };
    child.stdout.on("data", (c) => {
      stdout += c.toString();
      if (stdout.length > 64 * 1024) child.kill("SIGTERM");
    });
    child.stderr.on("data", (c) => {
      stderr += c.toString();
    });
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      finish(`Error: \u547D\u4EE4\u8D85\u65F6\uFF0830s\uFF09
stdout:
${stdout.slice(0, 4e3)}`);
    }, 3e4);
    child.on("close", (code) => {
      clearTimeout(timer);
      const out = stdout.slice(0, 8e3);
      const err = stderr.slice(0, 2e3);
      finish(`exit=${code}
stdout:
${out}${err ? `
stderr:
${err}` : ""}`);
    });
    child.on("error", (e) => {
      clearTimeout(timer);
      finish(`Error: \u6267\u884C\u5931\u8D25 - ${e.message}`);
    });
  });
}
async function execSendFeishu(args) {
  const chatId = String(args.chat_id || "");
  const text = String(args.text || "");
  if (!chatId || !text) return "Error: \u7F3A\u5C11 chat_id \u6216 text \u53C2\u6570";
  let token = "";
  try {
    token = JSON.parse(fs15.readFileSync(TOKEN_FILE, "utf-8")).accessToken || "";
  } catch (e) {
    return `Error: \u8BFB\u53D6\u98DE\u4E66 token \u5931\u8D25 - ${e.message}`;
  }
  if (!token) return "Error: \u98DE\u4E66 token \u4E3A\u7A7A";
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 1e4);
    const res = await fetch("https://open.feishu.cn/open-apis/im/v1/messages?receive_id_type=chat_id", {
      method: "POST",
      headers: { "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ receive_id: chatId, msg_type: "text", content: JSON.stringify({ text }) }),
      signal: ctrl.signal
    });
    clearTimeout(timer);
    const data = await res.json();
    return data.code === 0 ? `OK: \u6D88\u606F\u5DF2\u53D1\u9001\u5230 ${chatId}` : `Error: \u98DE\u4E66\u8FD4\u56DE code=${data.code} msg=${data.msg}`;
  } catch (e) {
    return `Error: \u53D1\u9001\u5931\u8D25 - ${e.message}`;
  }
}
async function execMemoryRecall(args) {
  const query2 = String(args.query || "");
  const limit = Number(args.limit) || 5;
  if (!query2) return "Error: \u7F3A\u5C11 query \u53C2\u6570";
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 1e4);
    const res = await fetch(`${AGENTMEMORY_URL}/agentmemory/smart-search`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: query2, limit }),
      signal: ctrl.signal
    });
    clearTimeout(timer);
    const data = await res.json();
    const results = data.results || [];
    if (!results.length) return "(\u65E0\u5339\u914D\u8BB0\u5FC6)";
    return results.map((r, i) => `${i + 1}. [${r.type || "?"}] ${(r.title || "").slice(0, 200)}`).join("\n");
  } catch (e) {
    return `Error: \u8BB0\u5FC6\u67E5\u8BE2\u5931\u8D25 - ${e.message}`;
  }
}
async function execMemorySave(args) {
  const content = String(args.content || "");
  const type = String(args.type || "fact");
  if (!content) return "Error: \u7F3A\u5C11 content \u53C2\u6570";
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 1e4);
    const res = await fetch(`${AGENTMEMORY_URL}/agentmemory/save`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content, type }),
      signal: ctrl.signal
    });
    clearTimeout(timer);
    return res.ok ? "OK: \u5DF2\u4FDD\u5B58\u5230\u957F\u671F\u8BB0\u5FC6" : `Error: \u4FDD\u5B58\u5931\u8D25 HTTP ${res.status}`;
  } catch (e) {
    return `Error: \u8BB0\u5FC6\u4FDD\u5B58\u5931\u8D25 - ${e.message}`;
  }
}
async function executeTool(call) {
  switch (call.name) {
    case "read_file":
      return execReadFile(call.args);
    case "write_file":
      return execWriteFile(call.args);
    case "list_files":
      return execListFiles(call.args);
    case "run_bash":
      return execRunBash(call.args);
    case "send_feishu_message":
      return execSendFeishu(call.args);
    case "memory_recall":
      return execMemoryRecall(call.args);
    case "memory_save":
      return execMemorySave(call.args);
    default:
      return `Error: \u672A\u77E5\u5DE5\u5177 ${call.name}`;
  }
}

