    resolvePendingPermission: (id, resolution) => pendingPerms.resolve(id, resolution) || pendingApprovals.resolve(id, resolution),
    resolvePendingStructuredInput: (requestId, resolution) => pendingStructuredInputs.resolve(requestId, resolution),
    waitForPendingPermission: (id) => pendingPerms.waitFor(id)
